import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百五十三章 月亮的阴晴圆缺","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/153第一百五十三章 月亮的阴晴圆缺.md","filePath":"meditation/巴利文大藏经/153第一百五十三章 月亮的阴晴圆缺.md"}'),_={name:"meditation/巴利文大藏经/153第一百五十三章 月亮的阴晴圆缺.md"};function r(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第一百五十三章-月亮的阴晴圆缺" tabindex="-1">第一百五十三章 月亮的阴晴圆缺 <a class="header-anchor" href="#第一百五十三章-月亮的阴晴圆缺" aria-label="Permalink to &quot;第一百五十三章 月亮的阴晴圆缺&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部16相应7经/教诫经第二(迦叶相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的竹林中，有一天，佛陀正在为出家弟子们说法，这时，佛陀对迦叶尊者说：“迦叶！你现在来为比丘们（出家人），说一些法，就像如来为他们说法那样。”</p><p>迦叶尊者说：“世尊，诸位学友们，任何的修行人，如果他们不相信善法；不反省、不检查自己的行为、言语、念想是否合乎于善法；当他们的行为做下恶事，犯下错误的时候不会感到羞愧、惭愧；他们不用善法作为自己行为做事的准则；这样的人就是愚昧无知的人，就是没有智慧的人，当然也可以预知，他们将会因为这样的行为离善法越来越远，他们将会忘失善法，离善道越来越远，他们将会由此堕入恶法黑暗的深渊之中，他们将会陷入无尽的烦恼和痛苦之中。</p><p>世尊，诸位学友们，就如同月亮由圆月变成月芽，最后消失不见一样。月亮在这个阶段，由满月变成凸月，由凸月变成下弦月，由下弦月变成娥眉月，由娥眉月变成新月消失不见，月亮能够看见的形体、容貌在逐渐的减损，月亮的圆相在逐渐的减损，月亮的光明在逐渐的消退，月亮能够看见的圆周和直径面积在减损，同样的道理，任何的修行人，如果他们不相信善法；不反省、不检查自己的行为、言语、念想是否合乎于善法；当他们的行为做下恶事，犯下错误的时候不会感到羞愧、惭愧；他们不用善法作为自己行为做事的准则；这样的人就是愚昧无知的人，就是没有智慧的人，当然也可以预知，他们将会因为这样的行为离善法越来越远，他们将会忘失善法，离善道越来越远，他们将会由此堕入恶法黑暗的深渊之中，他们将会陷入无尽的烦恼和痛苦之中。就如同月亮由圆月变成月芽，最后消失不见一样。</p><p>世尊，诸位学友们，不相信善法的人，这就是减损，这就消退；没有羞耻心，不反省自己，不忏悔自己错误行为的人，这就是减损，这就消退；松懈懒惰的人，这就是减损，这就消退；内心充满邪见，充满不正确见解的人，这就是减损，这就消退；容易生气、愤怒的人，这就是减损，这就消退；喜欢怨恨的人，这就是减损，这就消退；不接受正确教导，不接受正确劝解的人，这就是减损，这就消退。</p><p>世尊，诸位学友们，任何的修行人，如果他们相信善法；经常反省、检查自己的行为、言语、念想是否合乎于善法；当他们的行为做下恶事，犯下错误的时候就会感到羞愧、惭愧；他们用善法作为行为做事的准则；这样的人就是有智慧的人，当然也可以预知，他们将会因为这样的行为长久的安住在善法之中，他们将会走在带来幸福和快乐的善道之上，他们不会堕入恶法黑暗的深渊之中，他们不会陷入无尽的烦恼和痛苦之中。</p><p>世尊，诸位学友们，就如同月亮从无到有，由月芽变成圆月一样，月亮在这个阶段，由新月变成娥眉月，由娥眉月变成上弦月，由上弦月变成凸月，由凸月变成满月照亮黑夜，月亮能够看见的形体、容貌在逐渐的增长，月亮的圆相在逐渐的增长，月亮的光明在逐渐的增进，月亮能够看见的圆周和直径面积在增长，同样的道理，任何的修行人，如果他们相信善法；经常反省、检查自己的行为、言语、念想是否合乎于善法；当他们的行为做下恶事，犯下错误的时候会感到羞愧、惭愧；他们用善法作为自己行为做事的准则，这样的人就是有智慧的人，当然也可以预知，他们将会因为这样的行为长久的安住在善法之中，他们将会走在带来幸福和快乐的善道之上，他们不会堕入恶法黑暗的深渊之中，他们不会陷入无尽的烦恼和痛苦之中。就如同月亮从无到有，由月芽变成圆月一样。</p><p>世尊，诸位学友们，相信善法的人，这就是增长，这就增进；有羞耻心，经常反省自己，经常忏悔自己错误行为的人，这就是增长，这就增进；精进努力的人，这就是增长，这就增进；内心充满智慧，充满正确见解的人，这就是增长，这就增进；不生气、不愤怒的人，这就是增长，这就增进；不怨恨的人，这就是增长，这就增进；接受正确教导，接受正确劝解的人，这就是增长，这就增进。”</p><p>迦叶尊者说法后，佛陀说：“迦叶！你说的很好，弟子们，你们要按迦叶尊者所说的法去实践的修行，如来在这里印证他所说法的正确性，他现在所说的法，就如同如来所说的法一样，你们不要有任何的疑虑，应该按迦叶尊者所说的法去修行。”</p><p>佛陀和迦叶尊者说法后，听法的出家弟子们都再次的顶礼佛陀和迦叶尊者，随喜赞叹佛陀和迦叶尊者说法的无量功德，他们都按着佛陀和迦叶尊者所说的法去修行。</p>',12)]))}const f=e(_,[["render",r]]);export{m as __pageData,f as default};
